// Friendly fallbacks for any topic that remains in a grouped curriculum.
function buildLesson(title,subject,level,index=0){
 const direct=(window.LESSON_CONTENT[`${level} ${subject}`]||{})[title] || (window.LESSON_CONTENT[subject]||{})[title];
 if(direct)return direct;
 return L(`Build a clear foundation in ${title}.`,`This ${subject} lesson introduces ${title}. Learn the key terms, connect the idea to an example, practise the skill step by step, and check your understanding before moving on.`,[`Key idea: ${title}.`,`Use a simple real-life example before attempting harder questions.`],[`Define or describe ${title} in your own words.`,`Create one example and explain why it fits the topic.`],`Teach the main idea of ${title} to another learner in three clear steps.`);
}
